"""Audit reusable graph/presearch timing versus native-dependent source/budgets/labels."""
import json,hashlib,struct,csv,copy,sys,subprocess
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'experiments/prospective_external_family_corrected_native_epoch_v1_2026-10-19';E=R/'experiments';P=E/'prospective_external_family_supplementary_development_v1_2026-10-19';N=E/'prospective_external_family_native_shared_sink_native_v1_2026-10-19'
def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def f32(x):return struct.unpack('<f',struct.pack('<f',float(x)))[0]
def bits(x):return struct.pack('>f',float(x)).hex()
def main():
 proof=read(N/'verification.json');assert all(sha(k)==h for k,h in proof['bindings'].items());D.mkdir(exist_ok=False);bindings={str(N/'verification.json'):sha(N/'verification.json'),str(Path(__file__).resolve()):sha(__file__)};rows=[]
 for i in (1,2,3):
  case=f'w160/episode_{i:02d}';T=E/'prospective_external_family_frame_timings_v1_2026-10-19'/case;tp=T/'verification.json';v=read(tp);assert all(sha(k)==h for k,h in v['bindings'].items());q=T/'initial_connection_criticalities.json';payload=read(q);initial=N/case/'cold/native/initial_connections.tsv';native={(int(r['net']),int(r['pin'])):r for r in csv.DictReader(initial.open(),delimiter='\t')};assert len(native)==len(payload)==15616
  for r in payload:
   a=native[r['native_net_id'],r['local_sink_pin']];assert (int(a['source_rr']),int(a['sink_rr']))==(r['source_rr'],r['target_rr']);raw=f32(a['criticality']);assert bits(raw)==r['raw_criticality_bits'];maximum=f32(r['maximum_text']);assert f32(r['exponent_text'])==1
   transformed=min(f32(max(raw-(1.0-maximum),0.0)),maximum);assert bits(transformed)==r['criticality_bits']
  for p in (tp,q,initial):bindings[str(p)]=sha(p)
  spec=read(P/'specifications'/case/'comparison_spec.json');source=Path(spec['source_frame']);source_receipt=source.parent/'receipt.json';s=read(source_receipt);old_route=Path(s['source_route']);warm=P/'predictions'/case/'warm/native_retained/initial.json';bindings[str(source_receipt)]=sha(source_receipt);bindings[str(source)]=sha(source);bindings[str(old_route)]=sha(old_route);bindings[str(warm)]=sha(warm)
  rows.append(dict(case=case,initial_pin_identity_and_raw_float32_equal=True,transformed_float32_equal=True,connections=15616,old_source_route=str(old_route),old_warm_budget_reusable_for_corrected_source=False,corrected_cold_label_verification=str(N/case/'cold/native/verification.json')))
 repair=read(E/'prospective_external_family_primary_budget_repair_v1_2026-10-19/protocol.json');unavailable=repair['unavailable_cases'];assert len(unavailable)==6
 (D/'epoch_audit.json').write_text(json.dumps(dict(status='ALL3_CORRECTED_INITIAL_TIMING_EXACT_SOURCE_AND_BUDGET_REGENERATION_REQUIRED',rows=rows,unavailable_cases=unavailable,bindings=bindings,scope='Development-only. Original source/budgets/labels remain valid in original epoch, not corrupted. Graph/endpoint/floor can be reused by exact bindings. Old initial transformed timing matches actual new binary presearch outputs; no target path labels used for timing construction. No retrospective replacement of original forecast gates.'),indent=2)+'\n')
 base=read(E/'prospective_external_family_native_case_manifest_v1_2026-10-19/manifest.json');source=copy.deepcopy(next(c for c in base['cases'] if c['case']=='w160/source'));target=read(N/'manifest.json')['cases'][0];source['command']=target['command'].copy();source['output']=str(D/'native/w160/source');source['role']='corrected_native_source_conditioning_development';base['cases']=[source];base['full_workflow_admitted']=True;base['scope']='Single source native component, not full workflow time admission';base['bindings'].update({str(N/'manifest.json'):sha(N/'manifest.json'),str(D/'epoch_audit.json'):sha(D/'epoch_audit.json')});exe=Path(source['command'][0]);base['bindings'][str(exe)]=sha(exe)
 manifest=D/'source_manifest.json';manifest.write_text(json.dumps(base,indent=2)+'\n');(D/'protocol.json').write_text(json.dumps(dict(native_source_command=source['command'],source_inputs=source['inputs'],corrected_target_label_proofs=[r['corrected_cold_label_verification'] for r in rows],unavailable_cases=unavailable,source_and_warm_budget_regeneration_required=True,scope='New development semantic epoch; freeze same all3 and original unavailable6. Only cold source regenerated; existing corrected-native cold labels retained, cached presearch timing exact verified. Later forecasts need fresh source checkpoint + XML audit + warm budget derivation. No new scoring formula or target-driven selection.',bindings={str(manifest):sha(manifest),str(D/'epoch_audit.json'):sha(D/'epoch_audit.json')}),indent=2)+'\n')
 out=Path(source['output']);out.parent.mkdir(parents=True)
 with (D/'source_execution.log').open('x') as log:r=subprocess.run([sys.executable,str(R/'tools/run_external_native_route_case_v1.py'),str(manifest),'w160/source'],cwd=R,stdout=log,stderr=subprocess.STDOUT)
 vp=out/'verification.json';result=read(vp) if vp.exists() else {}; (D/'source_terminal.json').write_text(json.dumps(dict(exit_code=r.returncode,status=result.get('status','MISSING_VERIFICATION'),verification=str(vp)),indent=2)+'\n');print(result.get('status','MISSING_VERIFICATION'))
if __name__=='__main__':main()
